styles:
@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

/* ── FAQ div-based triggers — no button, no theme interference ── */
.p .fqbtn {
  width:100% !important; display:flex !important;
  justify-content:space-between !important; align-items:center !important;
  padding:21px 0 !important; cursor:pointer !important; gap:16px !important;
  background:none !important; background-color:transparent !important;
  background-image:none !important; background-clip:unset !important;
  -webkit-background-clip:unset !important; -webkit-text-fill-color:unset !important;
  border:none !important; outline:none !important;
  box-shadow:none !important; border-radius:0 !important;
  margin:0 !important; text-align:left !important;
  font-family:'Inter',sans-serif !important;
  color:inherit !important; text-decoration:none !important;
}
.p .fqbtn:hover { background:none !important; background-color:transparent !important; background-image:none !important; }
.p .fqq {
  font-size:16px !important; font-weight:500 !important;
  color:#C8C5D8 !important; -webkit-text-fill-color:#C8C5D8 !important;
  background:none !important; background-image:none !important;
  background-clip:unset !important; -webkit-background-clip:unset !important;
  flex:1 !important; font-family:'Inter',sans-serif !important;
}
.p .fqbtn:hover .fqq { color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important; }
.p .fqic {
  width:26px !important; height:26px !important; border-radius:50% !important;
  border:1px solid rgba(255,255,255,.15) !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  flex-shrink:0 !important; font-size:16px !important; line-height:1 !important;
  color:#8A87A0 !important; -webkit-text-fill-color:#8A87A0 !important;
  background:transparent !important; background-image:none !important;
  background-clip:unset !important; -webkit-background-clip:unset !important;
  transition:transform .3s, border-color .3s, color .3s !important;
  font-family:'Inter',sans-serif !important;
}
.p .fq.open .fqic {
  transform:rotate(45deg) !important;
  border-color:rgba(196,63,122,.5) !important;
  color:#C43F7A !important; -webkit-text-fill-color:#C43F7A !important;
  background:transparent !important;
}
.p .fq { background:transparent !important; background-image:none !important; }
.p .fqbody { max-height:0 !important; overflow:hidden !important; background:transparent !important; }
.p .fq.open .fqbody { max-height:280px !important; padding-bottom:22px !important; }
.p .fqa {
  font-size:14.5px !important; font-weight:300 !important; line-height:1.78 !important;
  color:#8A87A0 !important; -webkit-text-fill-color:#8A87A0 !important;
  background:none !important; background-image:none !important;
  background-clip:unset !important; -webkit-background-clip:unset !important;
  font-family:'Inter',sans-serif !important;
}
.p .fqa strong { color:#C8C5D8 !important; -webkit-text-fill-color:#C8C5D8 !important; font-weight:500 !important; }

/* ── Lightbox nav/close divs ── */
.p .lbbtn {
  width:34px !important; height:34px !important; border-radius:50% !important;
  background:rgba(255,255,255,.07) !important; background-image:none !important;
  background-color:rgba(255,255,255,.07) !important;
  background-clip:unset !important; -webkit-background-clip:unset !important;
  border:1px solid rgba(255,255,255,.15) !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  cursor:pointer !important; font-size:18px !important; line-height:1 !important;
  color:#8A87A0 !important; -webkit-text-fill-color:#8A87A0 !important;
  transition:all .2s !important; flex-shrink:0 !important;
  padding:0 !important; margin:0 !important; box-shadow:none !important;
  font-family:'Inter',sans-serif !important;
  text-align:center !important; user-select:none !important;
}
.p .lbbtn:hover {
  background:rgba(255,255,255,.14) !important;
  background-color:rgba(255,255,255,.14) !important;
  background-image:none !important;
  color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important;
}

/* ── Comparison table header spans — kill black box on STARTUP etc ── */
.p .thlbl {
  background:transparent !important; background-color:transparent !important;
  background-image:none !important; display:block !important;
  color:#8A87A0 !important; -webkit-text-fill-color:#8A87A0 !important;
  font-size:10px !important; font-weight:600 !important;
  letter-spacing:.14em !important; text-transform:uppercase !important;
  padding:0 !important; margin-bottom:10px !important;
}
.p .thname {
  background:transparent !important; background-color:transparent !important;
  background-image:none !important; background-clip:unset !important;
  -webkit-background-clip:unset !important;
  color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important;
  display:block !important; font-size:20px !important; font-weight:700 !important;
  letter-spacing:-.5px !important; margin-bottom:8px !important; padding:0 !important;
}
.p .thprice {
  background:transparent !important; background-color:transparent !important;
  background-image:none !important; background-clip:unset !important;
  -webkit-background-clip:unset !important; -webkit-text-fill-color:#F0EDF8 !important;
  color:#F0EDF8 !important; display:block !important;
  font-size:30px !important; font-weight:700 !important;
  letter-spacing:-1.5px !important; line-height:1 !important; margin-bottom:4px !important; padding:0 !important;
}
.p .thg .thprice {
  background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A) !important;
  background-size:300% 300% !important;
  -webkit-background-clip:text !important; -webkit-text-fill-color:transparent !important;
  background-clip:text !important; animation:gs 5s ease infinite !important;
}
.p .the .thprice { color:#FCD34D !important; -webkit-text-fill-color:#FCD34D !important; background:none !important; }
.p .thsub { color:#8A87A0 !important; -webkit-text-fill-color:#8A87A0 !important; background:transparent !important; background-image:none !important; display:block !important; font-size:11px !important; font-weight:300 !important; padding:0 !important; }
.p .thann { color:#22C55E !important; -webkit-text-fill-color:#22C55E !important; background:transparent !important; background-image:none !important; font-size:11px !important; font-weight:500 !important; padding:0 !important; }
.p .ct thead th { background-color:var(--bg3,#141122) !important; }
.p .ct thead th * { background-clip:unset !important; -webkit-background-clip:unset !important; }
.p .ct tbody td { color:#C8C5D8 !important; background-color:transparent !important; }
.p .ct tbody td:first-child { color:#F0EDF8 !important; }
/* ── Inter font — override any theme font ── */
.p, .p * { font-family:'Inter',sans-serif !important; font-weight:300 !important; }
.p h1,.p h2,.p h3,.p .pname,.p .hlh,.p .pt,.p .thname,.p .pc-name { font-weight:600 !important; }
.p .pbig,.p .thprice,.p .sbin { font-weight:700 !important; }
.p strong { font-weight:600 !important; }
.p .pbadge,.p .pbadge *,.p .bipill,.p .cs-tag,.p .cstag { font-weight:700 !important; }

/* ── SVG elements — transparent background, no exceptions ── */
.p svg, .p svg * { background:transparent !important; background-color:transparent !important; background-image:none !important; }
.p .hlico { background:transparent !important; background-color:transparent !important; background-image:none !important; border:none !important; }
.p .hlico svg { background:transparent !important; }
.p .pn { background:#0D0B18 !important; background-color:#0D0B18 !important; background-image:none !important; }
.p .pn svg { background:transparent !important; background-color:transparent !important; }
.p .piico { background:transparent !important; background-color:transparent !important; background-image:none !important; }
.p .piico svg { background:transparent !important; }
/* ── Annual pricing display ── */
.p .pann { display:none !important; }
.p .ann .pyr .mo { color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important; font-size:14px !important; font-weight:400 !important; }
.p .pyr > div, .p .pyr > div * { color:#22C55E !important; -webkit-text-fill-color:#22C55E !important; }

/* ── Tooltips — use JS-positioned div instead of ::after to avoid clip ── */
.p .dgs-tip { position:relative !important; cursor:help !important; }

/* ── Mobile comparison cards toggle ── */
.p .cmp-mobile { display:none; }
.p .proc { overflow:visible !important; }
.p .proc .ps { overflow:visible !important; }
.p .proc .pn { z-index:2 !important; position:relative !important; background:#0D0B18 !important; background-color:#0D0B18 !important; }

/* ── Tooltip — JS powered, body-level, never clips ── */
.p .dgs-tip { display:inline-flex !important; cursor:help !important; }
.dgs-tooltip-popup {
  position:fixed; z-index:999999; width:230px;
  background:#1B1530; border:1px solid rgba(196,63,122,.45);
  border-radius:10px; padding:12px 15px;
  font-family:'Inter',sans-serif; font-size:12.5px; font-weight:300;
  color:#C8C5D8; line-height:1.65;
  pointer-events:none; box-shadow:0 12px 40px rgba(0,0,0,.7);
  transition:opacity .15s; opacity:0; display:block;
}
.p .pci { overflow:visible !important; background:transparent !important; background-color:transparent !important; background-image:none !important; }
/* ── Growth hero card background ── */
.p .pc.ch { background:linear-gradient(160deg,rgba(232,97,42,.2),rgba(196,63,122,.25) 50%,rgba(98,71,176,.18)) !important; }
/* ── All plan card ticks ── */
.p .ck { color:#22C55E !important; -webkit-text-fill-color:#22C55E !important; background:transparent !important; background-image:none !important; font-size:14px !important; font-weight:700 !important; flex-shrink:0 !important; }
.p .pc.ch .pname { color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important; }
.p .pc.ch .pdesc { color:#C8C5D8 !important; -webkit-text-fill-color:#C8C5D8 !important; }
.p .pc.ch .pbig  { color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important; }
.p .pc.ch .pkw   { color:#C8C5D8 !important; -webkit-text-fill-color:#C8C5D8 !important; }
.p .pc.ch .pul li { color:#C8C5D8 !important; -webkit-text-fill-color:#C8C5D8 !important; }

/* ── Red cross for unavailable features ── */
.p .tn { color:#E55A5A !important; -webkit-text-fill-color:#E55A5A !important; font-size:16px !important; font-weight:500 !important; opacity:.7 !important; }

/* ── Icons — no background, no border ── */
.p .hlico { background:transparent !important; background-color:transparent !important; background-image:none !important; border:none !important; }

/* ── Bento proof images — contained properly ── */
.p .bento-row .bi img { width:100% !important; height:100% !important; object-fit:cover !important; object-position:top center !important; display:block !important; }

/* ── Table header children — no black background ── */
.p .ct thead th * { background-color:transparent !important; background-image:none !important; }
.p .ct thead th { background-color:#141122 !important; }
.p .ct thead th.thg { background:linear-gradient(180deg,rgba(232,97,42,.15),rgba(196,63,122,.1)) !important; }
/* ── recth badge in comparison — force visible ── */
.p .recth { background:linear-gradient(135deg,#E8612A,#C43F7A) !important; background-image:linear-gradient(135deg,#E8612A,#C43F7A) !important; color:#fff !important; -webkit-text-fill-color:#fff !important; display:inline-block !important; font-size:10px !important; font-weight:700 !important; letter-spacing:.1em !important; text-transform:uppercase !important; padding:6px 16px !important; border-radius:100px !important; margin-bottom:10px !important; box-shadow:0 4px 14px rgba(196,63,122,.4) !important; }
/* ── Floating Most Preferred badge on comparison table ── */
.p .cmpt-outer { position:relative !important; padding-top:28px !important; overflow:visible !important; }
.p .recbadge-cmp-wrap { position:absolute !important; top:0 !important; z-index:20 !important; }
.p .recbadge-cmp { background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0) !important; background-image:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0) !important; color:#fff !important; -webkit-text-fill-color:#fff !important; }
/* ── Growth comparison column warm gradient ── */
.p .ct thead th.thg { background:linear-gradient(180deg,rgba(232,97,42,.18),rgba(196,63,122,.14) 60%,rgba(98,71,176,.1)) !important; }
.p .ct tbody td.tdg { background:linear-gradient(180deg,rgba(232,97,42,.07),rgba(196,63,122,.05)) !important; }
.p .ct thead th.thg > * { color:#F0EDF8 !important; -webkit-text-fill-color:#F0EDF8 !important; background-color:transparent !important; background-image:none !important; }
.p .ct thead th.thg .thprice { background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A) !important; background-size:300% 300% !important; -webkit-background-clip:text !important; -webkit-text-fill-color:transparent !important; background-clip:text !important; animation:gs 5s ease infinite !important; }
/* ── Plan card borders clip within radius ── */
.p .pc.cs,.p .pc.cd,.p .pc.ce { overflow:hidden !important; border-radius:18px !important; }
.p .pc.ch { border-top:none !important; border-image:none !important; }

.p .tdg { background:rgba(232,97,42,.04) !important; }

.p * { font-family:'Inter',sans-serif; box-sizing:border-box; margin:0; padding:0; }
.p a { text-decoration:none; color:inherit; }
.p img { display:block; max-width:100%; }
.p {
  background:#07060D; color:#C8C5D8;
  font-family:'Inter',sans-serif;
  font-size:15px; font-weight:300; line-height:1.7;
  overflow-x:hidden; -webkit-font-smoothing:antialiased;
  --bg:#07060D; --bg2:#0D0B18; --bg3:#141122;
  --silver:#F0EDF8; --body:#C8C5D8; --muted:#8A87A0; --dim:#5C596E;
  --line:rgba(255,255,255,.08); --ln2:rgba(255,255,255,.15);
  --green:#22C55E; --gold:#F59E0B;
}

@keyframes gs  { 0%,100%{background-position:0% 50%} 50%{background-position:100% 50%} }
@keyframes bk  { 0%,100%{opacity:1} 50%{opacity:.2} }
@keyframes mqr { 0%{transform:translateX(0)} 100%{transform:translateX(-50%)} }
@keyframes gl  { 0%,100%{box-shadow:0 0 0 0 rgba(196,63,122,.2)} 50%{box-shadow:0 0 0 12px rgba(196,63,122,.04)} }

/* GRADIENT TEXT */
.p .gt {
  background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A);
  background-size:300% 300%;
  -webkit-background-clip:text; -webkit-text-fill-color:transparent;
  background-clip:text; animation:gs 5s ease infinite;
}

/* REVEAL */
.p .rv { opacity:0; transform:translateY(20px); transition:opacity .55s,transform .55s; }
.p .rv.in { opacity:1; transform:translateY(0); }

/* LAYOUT */
.p .w  { max-width:1360px; margin:0 auto; padding:0 48px; }
.p .wm { max-width:1100px; margin:0 auto; padding:0 48px; }
.p .ws { max-width:760px;  margin:0 auto; padding:0 48px; }
.p .sec { padding:88px 0; border-bottom:1px solid var(--line); overflow:visible; }

/* EYEBROW */
.p .ew { display:inline-flex; align-items:center; gap:10px; font-size:10px; font-weight:700; letter-spacing:.22em; text-transform:uppercase; margin-bottom:14px; }
.p .ewt { background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A); background-size:300% 300%; -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; animation:gs 5s ease infinite; }
.p .ewl { width:18px; height:1px; background:linear-gradient(90deg,#E8612A,#6247B0); flex-shrink:0; }

/* SECTION HEADER */
.p .sh { text-align:center; margin-bottom:56px; }
.p .sh h2 { font-size:clamp(30px,4vw,52px); font-weight:600; letter-spacing:-2px; color:var(--silver); line-height:1.07; margin-bottom:12px; }
.p .sh p  { font-size:15px; color:var(--muted); max-width:520px; margin:0 auto; font-weight:300; }

/* ── HERO ── */
.p .hero { padding:96px 0 128px; text-align:center; position:relative; overflow:hidden; }
.p .hero::before { content:''; position:absolute; top:-260px; left:50%; transform:translateX(-50%); width:900px; height:640px; background:radial-gradient(ellipse at 50% 35%,rgba(196,63,122,.12) 0%,rgba(98,71,176,.07) 42%,transparent 70%); pointer-events:none; z-index:0; }
.p .hero::after  { content:''; position:absolute; bottom:0; left:0; right:0; height:150px; background:linear-gradient(to bottom,transparent,#07060D); pointer-events:none; z-index:1; }
.p .hero .w { position:relative; z-index:2; }
.p .hbadge { display:inline-flex; align-items:center; gap:8px; border:1px solid var(--ln2); border-radius:100px; padding:7px 18px; font-size:11px; color:var(--muted); margin-bottom:28px; background:rgba(255,255,255,.03); }
.p .dot { width:7px; height:7px; border-radius:50%; background:var(--green); animation:bk 2s infinite; flex-shrink:0; }
.p .hero h1 { font-size:clamp(48px,7vw,96px); font-weight:600; letter-spacing:-4px; line-height:.95; color:var(--silver); margin-bottom:22px; }
.p .hsub { font-size:17px; font-weight:300; color:var(--muted); max-width:520px; margin:0 auto 52px; line-height:1.8; }
.p .sbar { display:inline-flex; border:1px solid var(--ln2); border-radius:14px; overflow:hidden; background:var(--bg2); }
.p .sbi  { padding:18px 32px; border-right:1px solid var(--line); text-align:center; }
.p .sbi:last-child { border-right:none; }
.p .sbin { font-size:22px; font-weight:700; letter-spacing:-1px; color:var(--silver); display:block; line-height:1; }
.p .sbil { font-size:11px; font-weight:300; color:var(--muted); margin-top:5px; display:block; }

/* ── FEATURE HIGHLIGHTS ── */
.p .hlg { display:grid; grid-template-columns:repeat(3,1fr); gap:18px; }
.p .hlc { background:var(--bg2); border:1px solid var(--line); border-radius:16px; padding:30px 26px; position:relative; overflow:hidden; transition:border-color .25s,transform .25s; }
.p .hlc:hover { border-color:var(--ln2); transform:translateY(-4px); }
.p .hlc::before { content:''; position:absolute; top:0; left:0; right:0; height:2px; background:linear-gradient(90deg,#E8612A,#C43F7A,#6247B0); opacity:.55; transition:opacity .25s; }
.p .hlc:hover::before { opacity:1; }
.p .hlico { width:46px; height:46px; border-radius:0; display:flex; align-items:center; justify-content:center; margin-bottom:18px; border:none; background:transparent; }
.p .hlico svg { width:22px; height:22px; stroke-width:1.5; fill:none; stroke:url(#ig); }
.p .hlh { font-size:16px; font-weight:600; color:var(--silver); margin-bottom:9px; }
.p .hlt { font-size:13.5px; color:var(--muted); line-height:1.7; font-weight:300; }

/* ── PROOF BENTO ── */
.p .bento-row { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; }
.p .bi { border-radius:14px; overflow:hidden; border:1px solid var(--line); background:var(--bg2); position:relative; cursor:pointer; transition:transform .3s cubic-bezier(.22,1,.36,1),border-color .3s,box-shadow .3s; }
.p .bi:hover { transform:translateY(-5px); border-color:var(--ln2); box-shadow:0 20px 50px rgba(0,0,0,.5); }
.p .bi img { width:100%; height:100%; object-fit:cover; display:block; transition:transform .5s; }
.p .bi:hover img { transform:scale(1.04); }
.p .bio  { position:absolute; bottom:0; left:0; right:0; padding:14px 16px; background:linear-gradient(to top,rgba(7,6,13,.92),transparent); }
.p .bipill { display:inline-block; font-size:9px; font-weight:700; letter-spacing:.14em; text-transform:uppercase; padding:3px 9px; border-radius:5px; background:linear-gradient(135deg,#E8612A,#C43F7A); color:#fff; margin-bottom:5px; }
.p .bittl { font-size:13px; font-weight:500; color:var(--silver); }
.p .bizoom { position:absolute; top:10px; right:10px; width:30px; height:30px; border-radius:7px; background:rgba(0,0,0,.55); border:1px solid var(--ln2); display:flex; align-items:center; justify-content:center; opacity:0; transition:opacity .2s; }
.p .bizoom svg { width:13px; height:13px; stroke:#fff; stroke-width:2; fill:none; }
.p .bi:hover .bizoom { opacity:1; }

/* ── LIGHTBOX ── */
.p .lb { position:fixed; inset:0; z-index:99999; background:rgba(3,2,9,.95); backdrop-filter:blur(22px); display:none; flex-direction:column; }
.p .lb.on { display:flex; }
.p .lbtop { display:flex; align-items:center; justify-content:space-between; padding:14px 24px; border-bottom:1px solid var(--line); background:rgba(13,11,24,.97); flex-shrink:0; }
.p .lbtl { display:flex; align-items:center; gap:12px; }
.p .lbpill { display:inline-block; font-size:9px; font-weight:700; letter-spacing:.14em; text-transform:uppercase; padding:4px 10px; border-radius:5px; background:linear-gradient(135deg,#E8612A,#C43F7A); color:#fff; }
.p .lbttl { font-size:15px; font-weight:500; color:var(--silver); }
.p .lbr { display:flex; align-items:center; gap:8px; }
.p .lbcount { font-size:12px; font-weight:300; color:var(--muted); }
.p .lbbtn { width:34px; height:34px; border-radius:50%; background:rgba(255,255,255,.07); border:1px solid var(--ln2); display:flex; align-items:center; justify-content:center; cursor:pointer; color:var(--muted); transition:all .2s; font-size:18px; line-height:1; }
.p .lbbtn:hover { background:rgba(255,255,255,.14); color:var(--silver); }
/* Horizontal scroll body */
.p .lbbody {
  flex:1;
  overflow-x:auto;
  overflow-y:hidden;
  display:flex;
  align-items:center;
  padding:32px;
  gap:20px;
  scroll-behavior:smooth;
}
.p .lbbody::-webkit-scrollbar { height:4px; }
.p .lbbody::-webkit-scrollbar-track { background:rgba(255,255,255,.04); }
