.p .csbody { padding:22px 26px 24px; }
.p .cslogo { height:30px; margin-bottom:13px; }
.p .cslogo img { height:100%; width:auto; object-fit:contain; }
.p .cstag { display:inline-block; font-size:9px; font-weight:700; letter-spacing:.14em; text-transform:uppercase; padding:4px 11px; border-radius:100px; margin-bottom:12px; background:rgba(232,97,42,.1); color:#E8612A; border:1px solid rgba(232,97,42,.2); }
