.p .csbody > p { font-size:13px; color:var(--muted); line-height:1.68; margin-bottom:18px; font-weight:300; }
.p .csnums { display:grid; grid-template-columns:repeat(3,1fr); gap:9px; margin-bottom:14px; }
.p .cnum { text-align:center; padding:12px 5px; background:rgba(255,255,255,.03); border:1px solid var(--line); border-radius:8px; }
.p .cnum strong { display:block; font-size:20px; font-weight:700; letter-spacing:-1px; line-height:1; background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A); background-size:300% 300%; -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; animation:gs 5s ease infinite; }
.p .cnum span { font-size:10px; font-weight:500; color:var(--dim); text-transform:uppercase; letter-spacing:.04em; margin-top:3px; display:block; }
.p .csview { display:inline-flex; align-items:center; gap:5px; font-size:12px; font-weight:500; background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A); background-size:300% 300%; -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; animation:gs 5s ease infinite; }
.p .csft { padding:12px 26px; border-top:1px solid var(--line); display:flex; align-items:center; gap:9px; }
.p .csav { width:25px; height:25px; border-radius:6px; font-size:9px; font-weight:700; display:flex; align-items:center; justify-content:center; background:linear-gradient(135deg,#E8612A,#C43F7A); color:#fff; flex-shrink:0; }
.p .csfn { font-size:12px; color:var(--muted); }
.p .cstm { margin-left:auto; font-size:11px; color:var(--dim); }

/* ── PROCESS ── */
.p .proc { display:grid; grid-template-columns:repeat(6,1fr); gap:0; position:relative; overflow:visible; padding-top:4px; }
.p .proc::before { content:''; position:absolute; top:32px; left:calc(100%/12); right:calc(100%/12); height:1px; background:linear-gradient(90deg,rgba(232,97,42,.4),rgba(196,63,122,.5),rgba(98,71,176,.4)); z-index:0; }
.p .ps  { text-align:center; padding:0 10px; position:relative; overflow:visible; }
.p .pn  { width:60px; height:60px; border-radius:50%; display:flex; align-items:center; justify-content:center; margin:0 auto 16px; background:var(--bg2,#0D0B18); position:relative; z-index:2; flex-shrink:0; }
.p .ps:nth-child(1) .pn { box-shadow:0 0 0 1.5px rgba(232,97,42,.6); }
.p .ps:nth-child(2) .pn { box-shadow:0 0 0 1.5px rgba(210,54,98,.6); }
