.p .pn svg { width:22px; height:22px; stroke-width:1.5; fill:none; stroke-linecap:round; stroke-linejoin:round; }
.p .ps:nth-child(1) .pn svg { stroke:rgba(232,97,42,.9); }
.p .ps:nth-child(2) .pn svg { stroke:rgba(210,54,98,.9); }
.p .ps:nth-child(3) .pn svg { stroke:rgba(180,46,126,.9); }
.p .ps:nth-child(4) .pn svg { stroke:rgba(145,50,148,.9); }
.p .ps:nth-child(5) .pn svg { stroke:rgba(115,58,162,.9); }
.p .ps:nth-child(6) .pn svg { stroke:rgba(98,71,176,.9); }
.p .pt { font-size:13px; font-weight:600; color:var(--silver); margin-bottom:6px; }
.p .pd { font-size:12px; color:var(--muted); line-height:1.6; font-weight:300; }

/* ── BILLING TOGGLE ── */
.p .togrow { display:flex; align-items:center; justify-content:center; gap:14px; margin-bottom:44px; }
.p .tl { font-size:15px; font-weight:400; color:var(--muted); transition:color .2s; }
.p .tl.on { color:var(--silver); font-weight:600; }
.p .tg { width:50px; height:26px; background:var(--bg3); border-radius:100px; cursor:pointer; border:1px solid var(--ln2); position:relative; transition:background .3s; flex-shrink:0; }
.p .tg.on { background:#C43F7A; }
.p .tg span { position:absolute; top:3px; left:3px; width:18px; height:18px; background:#fff; border-radius:50%; transition:transform .3s cubic-bezier(.22,1,.36,1); box-shadow:0 1px 4px rgba(0,0,0,.3); }
.p .tg.on span { transform:translateX(24px); }
.p .spill { background:rgba(34,197,94,.12); border:1px solid rgba(34,197,94,.24); color:#22C55E; font-size:10px; font-weight:600; letter-spacing:.08em; text-transform:uppercase; padding:4px 11px; border-radius:100px; }

/* ── PLAN CARDS ── */
.p .pgrid { display:grid; grid-template-columns:repeat(4,1fr); gap:20px; align-items:start; padding-top:30px; }
.p .pc { border-radius:18px; border:1px solid var(--ln2); background:var(--bg2); position:relative; overflow:visible; transition:transform .3s cubic-bezier(.22,1,.36,1),box-shadow .3s; }
/* No ::before on the card itself — it leaks outside border-radius when overflow:visible */
.p .pc::before { display:none !important; content:none !important; }
/* Accent line lives inside .pci which clips it cleanly */
.p .pc.cs { border-top:3px solid #38BDF8; border-radius:18px; overflow:hidden; }
.p .pc.cd { border-top:3px solid #A855F7; border-radius:18px; overflow:hidden; }
.p .pc.ce { border-top:3px solid #F59E0B; border-radius:18px; overflow:hidden; }
.p .pc:not(.ch):hover { transform:translateY(-5px); box-shadow:0 18px 50px rgba(0,0,0,.4); }

/* GROWTH HERO CARD */
.p .pc.ch {
  border:none;
  background:linear-gradient(160deg,rgba(232,97,42,.14),rgba(196,63,122,.18) 50%,rgba(98,71,176,.12));
  transform:translateY(-14px);
  animation:gl 3s ease-in-out infinite;
}
.p .pc.ch .pci {
  background:transparent !important;
  background-image:none !important;
  background-color:transparent !important;
}
.p .pc.ch::before { display:none; }
.p .pc.ch::after { content:''; position:absolute; inset:0; border-radius:18px; padding:1.5px; background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0,#C43F7A,#E8612A); background-size:300% 300%; animation:gs 4s ease infinite; -webkit-mask:linear-gradient(#fff 0 0) content-box,linear-gradient(#fff 0 0); -webkit-mask-composite:xor; mask-composite:exclude; pointer-events:none; }
.p .pc.ch:hover { transform:translateY(-20px); box-shadow:0 32px 70px rgba(196,63,122,.22); }

/* RECOMMENDED BADGE — sits above card, clears card top */
.p .recbadge {
  position:absolute; top:-20px; left:50%; transform:translateX(-50%);
  background:linear-gradient(135deg,#E8612A,#C43F7A,#6247B0);
  color:#fff; font-size:11px; font-weight:700; letter-spacing:.1em; text-transform:uppercase;
  padding:7px 24px; border-radius:100px; white-space:nowrap;
  box-shadow:0 6px 20px rgba(196,63,122,.45); z-index:5;
}
/* hero card inner gets extra top padding so content aligns with other cards */
