.p .pci { padding:32px 24px 28px; position:relative; }
.p .pbadge { display:inline-block; font-size:9px; font-weight:700; letter-spacing:.13em; text-transform:uppercase; padding:4px 11px; border-radius:5px; margin-bottom:12px; }
