.p .nc { flex-shrink:0; width:168px; height:74px; border-radius:8px; border:1px solid var(--line); background:rgba(255,255,255,.02); display:flex; align-items:center; justify-content:center; padding:9px 13px; transition:all .28s; overflow:hidden; }
